  talento: { title: "Human talent", subtitle: "Employee directory", panelTitle: "Talent — Employees", intro: "Employee directory for your businesses. No SSN or bank details.", introAdmin: " As an administrator you can create, edit and delete.", introViewer: " Your trial role is read-only.", loading: "Loading…", empty: "No employees yet.", searchAria: "Search employees", searchPlaceholder: "Search by name, role or contact…", thNombre: "Name", thPuesto: "Role", thContacto: "Contact", thIngreso: "Start date", thEstado: "Status", thAcciones: "Actions", edit: "Edit", delete: "Delete", editTitle: "Edit employee", newTitle: "New employee", nameAria: "Name", puestoAria: "Role", contactoAria: "Contact", ingresoAria: "Start date", estadoAria: "Status", notasAria: "Notes", namePlaceholder: "Name *", puestoPlaceholder: "Role", contactoPlaceholder: "Contact (email or phone)", notasPlaceholder: "Notes", estadoActivo: "Active", estadoInactivo: "Inactive", saving: "Saving…", saveChanges: "Save changes", create: "Create employee", cancel: "Cancel", msgCreated: "Employee \"{nombre}\" created.", msgUpdated: "Employee \"{nombre}\" updated.", msgDeleted: "Employee \"{nombre}\" deleted.", confirmDelete: "Delete employee \"{nombre}\"? This action cannot be undone.", errSave: "Could not save the employee.", errDelete: "Could not delete the employee." },
